-- Postcheck 330 (solo lectura, UNA consulta). Esperado: todo OK.
select n, control, actual, esperado, case when ok then 'OK' else 'FALLA' end as estado from (
  select 1 as n, 'las 2 tablas existen con RLS activa' as control, (select count(*) from pg_class where relnamespace = 'public'::regnamespace and relname in ('hostinger_estado_buzon', 'hostinger_respuestas_pendientes') and relrowsecurity)::text as actual, '2' as esperado,
         (select count(*) from pg_class where relnamespace = 'public'::regnamespace and relname in ('hostinger_estado_buzon', 'hostinger_respuestas_pendientes') and relrowsecurity) = 2 as ok
  union all select 2, 'anon y authenticated sin NINGÚN privilegio sobre las 2 tablas', (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('hostinger_estado_buzon', 'hostinger_respuestas_pendientes') and grantee in ('anon', 'authenticated', 'PUBLIC'))::text, '0',
         (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('hostinger_estado_buzon', 'hostinger_respuestas_pendientes') and grantee in ('anon', 'authenticated', 'PUBLIC')) = 0
  union all select 3, 'las 2 tablas no tienen policies (solo service_role)', (select count(*) from pg_policies where schemaname = 'public' and tablename in ('hostinger_estado_buzon', 'hostinger_respuestas_pendientes'))::text, '0',
         (select count(*) from pg_policies where schemaname = 'public' and tablename in ('hostinger_estado_buzon', 'hostinger_respuestas_pendientes')) = 0
  union all select 4, 'las 2 funciones existen, son SECURITY DEFINER y solo service_role puede ejecutarlas', (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('hostinger_estado_leer', 'hostinger_estado_avanzar') and p.prosecdef and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute'))::text, '2',
         (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('hostinger_estado_leer', 'hostinger_estado_avanzar') and p.prosecdef and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute')) = 2
) q order by n;
